unsafe fn readBitsFromReversedStream(
    mut bitpointer: *mut size_t,
    mut bitstream: *const c_uchar,
    mut nbits: size_t,
) -> c_uint {
    let mut result: c_uint = 0 as c_uint;
    if nbits == 0 as size_t {
        return 0 as c_uint;
    }

    // SAFETY: `bitpointer` is valid per the original function's contract; we only load its current value.
    let mut bp: size_t = unsafe { *bitpointer };
    let mut byte_index: size_t = bp >> 3;
    let mut bit_index: size_t = bp & 7;
    let mut remaining: size_t = nbits;

    while remaining != 0 as size_t {
        // SAFETY: `bitstream` is valid for the same bytes the original per-bit loop would access;
        // `byte_index` tracks the current byte containing the next unread reversed-stream bits.
        let byte: c_uint = unsafe { *bitstream.add(byte_index) as c_uint };
        let available: size_t = bit_index.wrapping_add(1 as size_t);
        let take: size_t = if remaining < available { remaining } else { available };
        let shift: size_t = available.wrapping_sub(take);
        let mask: c_uint = if take >= 32 as size_t {
            !0 as c_uint
        } else {
            (((1 as c_uint) << take) as c_uint).wrapping_sub(1 as c_uint)
        };
        let chunk: c_uint = (byte >> shift) & mask;

        result = (result << take) | chunk;
        remaining = remaining.wrapping_sub(take);

        if shift == 0 as size_t {
            byte_index = byte_index.wrapping_add(1 as size_t);
            bit_index = 7 as size_t;
        } else {
            bit_index = shift.wrapping_sub(1 as size_t);
        }
    }

    bp = bp.wrapping_add(nbits);
    // SAFETY: `bitpointer` is valid per the original function's contract; we store back the advanced bit position.
    unsafe {
        *bitpointer = bp;
    }
    result
}

